/* ============ CONTENIDO: CARRERA ============ */
const lk = (id, t) => '<button class="linkb" type="button" data-go="' + id + '">' + t + "</button>";
const acc = (items, open) => items.map((it, i) => '<details class="item"' + (open && i === 0 ? " open" : "") + "><summary>" + it[0] + '</summary><div class="body prose">' + it[1] + "</div></details>").join("");
const pg = (ey, t, lead, body) => '<p class="eyebrow">' + ey + "</p><h1>" + t + '</h1><p class="lead">' + lead + "</p>" + body;

const MALLA = [
  ["1.er año · Ciencias básicas", "Cálculo I y II, Álgebra lineal, Física (mecánica), Química general, Introducción a la ingeniería, Programación (Python), Comunicación efectiva.", "Base matemática para todo lo que viene: derivadas para optimizar, matrices para programación lineal, programación para automatizar análisis.", [["descriptiva", "Estadística descriptiva"], ["conversor", "Conversor de unidades"]]],
  ["2.º año · Ciencias de la ingeniería", "Cálculo III y ecuaciones diferenciales, Probabilidad y estadística, Física (electricidad, termodinámica), Mecánica, Economía (micro y macro), Contabilidad.", "La estadística es la herramienta más usada en la práctica profesional: calidad, pronósticos, muestreo, simulación.", [["muestra", "Tamaño de muestra"], ["regresion", "Regresión"], ["ratios", "Indicadores financieros"]]],
  ["3.er año · Núcleo industrial", "Investigación de operaciones I y II, Inferencia estadística, Ingeniería económica, Costos, Procesos industriales, Mecánica de fluidos, Ciencia de materiales.", "Aquí nace el «ingeniero que optimiza»: modelos matemáticos para decidir con recursos limitados.", [["programacion-lineal", "Programación lineal"], ["van-tir", "VAN y TIR"], ["costeo", "Costeo"]]],
  ["4.º año · Gestión de operaciones", "Gestión de operaciones, Logística y cadena de suministro, Control de calidad, Estudio del trabajo y ergonomía, Finanzas, Marketing, Gestión de personas, Simulación.", "Lo que más se usa en planta: inventarios, planificación, calidad, tiempos estándar.", [["eoq", "EOQ"], ["control-xr", "Control X̄-R"], ["tiempo-estandar", "Tiempo estándar"]]],
  ["5.º año · Integración y especialidad", "Preparación y evaluación de proyectos, Gestión estratégica, Diseño de sistemas productivos (layout), Prevención de riesgos, Electivos (data analytics, lean six sigma, minería, retail), Taller de innovación.", "Se integra todo en proyectos reales: diagnóstico, propuesta, evaluación económica e informe.", [["flujo-caja", "Flujo de caja"], ["cpm", "Ruta crítica"], ["iper", "Matriz IPER"]]],
  ["6.º año · Práctica profesional y memoria", "Práctica profesional (1 o 2), Seminario de título, Memoria o proyecto de título, Examen de grado.", "Demuestras que puedes resolver un problema real de una organización con método y evaluarlo económicamente.", [["practica-titulo", "Guía de práctica y memoria"], ["generador-informe", "Generador de informe"]]]
];
function pgMallaGen(){
  return pg("Carrera · Ingeniería Civil Industrial", "Mapa de la carrera", "Ruta típica de una carrera de Ingeniería Civil Industrial en Chile (11 a 12 semestres). Cada etapa enlaza con las herramientas de esta app que la aplican.",
    '<div class="steps">' + MALLA.map((m, i) => '<div class="step"><span class="sn">' + (i + 1) + '</span><div class="sb"><h4>' + m[0] + '</h4><p class="q">' + m[1] + '</p><p class="why"><b>Para qué sirve:</b> ' + m[2] + '</p><div class="quick" style="margin-top:8px">' + m[3].map(x => '<button class="chip" type="button" data-go="' + x[0] + '">' + x[1] + "</button>").join("") + "</div></div></div>").join("") + "</div>" +
    note("Ingeniería Civil Industrial (licenciatura en ciencias de la ingeniería, 6 años aprox.) tiene más base matemática y de investigación de operaciones; Ingeniería de Ejecución Industrial (4 años aprox.) se enfoca en la operación. Ambas trabajan en las mismas áreas.", "info") +
    h3("Competencias de egreso") + table(["Competencia", "Qué significa en la práctica"], [["Modelar y optimizar", "Traducir un problema real a variables, restricciones y objetivo; resolverlo y explicar la solución."], ["Evaluar económicamente", "Decidir con VAN, TIR, costos y riesgo; defender una inversión ante la gerencia."], ["Gestionar operaciones", "Planificar producción, inventarios, calidad y mantenimiento con indicadores."], ["Analizar datos", "Limpiar, visualizar y modelar datos (Excel, Power BI, Python, SQL)."], ["Liderar personas y proyectos", "Coordinar equipos multidisciplinarios, negociar y comunicar resultados por escrito y oralmente."], ["Actuar con ética y sostenibilidad", "Considerar seguridad, ambiente, comunidad y cumplimiento legal en cada decisión."]]));
}

const AREAS = [
  ["Operaciones y producción", "Jefe de producción, ingeniero de procesos, planificador, ingeniero de mejora continua.", "OEE, cumplimiento del plan, productividad, costo unitario, scrap.", "Lean, balanceo, tiempos estándar, programación, VSM.", ["oee", "balanceo", "vsm"]],
  ["Logística y cadena de suministro", "Analista de supply chain, planificador de demanda, jefe de bodega, comprador, ingeniero de transporte.", "Nivel de servicio (OTIF), rotación, días de inventario, costo logístico/venta, fill rate.", "Pronósticos, EOQ, stock de seguridad, ABC, ruteo, localización.", ["pronosticos", "stock-seguridad", "transporte"]],
  ["Calidad", "Ingeniero de calidad, auditor ISO, analista Six Sigma, jefe de aseguramiento.", "PPM, Cpk, costo de no calidad, reclamos, rendimiento al primer intento.", "SPC, capacidad, AMEF, Pareto, Ishikawa, DMAIC, ISO 9001.", ["control-xr", "capacidad", "amef"]],
  ["Finanzas y control de gestión", "Analista financiero, controller, analista de costos, evaluador de proyectos, banca.", "EBITDA, margen, ROE, VAN, presupuesto vs real.", "Flujo de caja, costeo, WACC, indicadores financieros, modelos en Excel.", ["flujo-caja", "wacc", "ratios"]],
  ["Proyectos e inversión", "Jefe de proyecto, PMO, ingeniero de proyectos, project controls.", "Avance físico vs programado, SPI, CPI, desviación de costo.", "CPM/PERT, Gantt, valor ganado, evaluación de proyectos.", ["cpm", "van-tir", "simulacion-mc"]],
  ["Seguridad, salud y medio ambiente (HSE)", "Ingeniero en prevención, coordinador HSE, encargado de sostenibilidad.", "Tasa de accidentabilidad, IF, IG, huella de carbono, cumplimiento legal.", "IPER, investigación de accidentes, ergonomía, ISO 45001 y 14001.", ["iper", "accidentabilidad", "huella"]],
  ["Análisis de datos y transformación digital", "Data analyst, BI developer, ingeniero de procesos digitales, consultor.", "Calidad de datos, adopción, ahorro por automatización.", "SQL, Power BI, Python, estadística, simulación, optimización.", ["regresion", "simulacion-mc", "programacion-lineal"]],
  ["Consultoría y estrategia", "Consultor de gestión, analista de estrategia, business analyst.", "Impacto económico de las recomendaciones.", "Estructuración de problemas, FODA, modelos de negocio, presentaciones ejecutivas.", ["foda", "canvas", "factores"]],
  ["Gestión de personas y comercial", "Analista de compensaciones, HR business partner, product manager, key account manager.", "Rotación, ausentismo, productividad por persona, margen comercial.", "Dotación, curvas de aprendizaje, precios, punto de equilibrio.", ["aprendizaje", "equilibrio", "costeo"]]
];
function pgAreas(){
  return pg("Carrera · Campo laboral", "Áreas de desempeño", "Dónde trabaja un ingeniero industrial, qué cargos ocupa, con qué indicadores lo evalúan y qué herramientas usa a diario.",
    acc(AREAS.map(a => [a[0], "<p><b>Cargos típicos:</b> " + a[1] + "</p><p><b>Indicadores (KPI) por los que te evalúan:</b> " + a[2] + "</p><p><b>Herramientas y métodos:</b> " + a[3] + '</p><div class="quick">' + a[4].map(id => C[id] ? '<button class="chip" type="button" data-go="' + id + '">' + C[id].t + "</button>" : "").join("") + "</div>"]), true) +
    h3("Industrias que más contratan en Chile") + '<div class="prose"><ul><li><b>Minería</b> y sus proveedores: mantenimiento, abastecimiento, proyectos, productividad.</li><li><b>Retail y consumo masivo</b>: supply chain, planificación comercial, e-commerce.</li><li><b>Banca, seguros y fintech</b>: riesgo, analítica, procesos, producto.</li><li><b>Manufactura y alimentos</b> (agroindustria, salmonicultura, vitivinicultura): producción, calidad, inocuidad.</li><li><b>Energía, construcción y servicios</b>: proyectos, contratos, control de gestión.</li><li><b>Consultoras</b> de gestión y tecnología, y <b>sector público</b> (evaluación social de proyectos, salud).</li></ul></div>');
}

function pgCompetencias(){
  return pg("Carrera · Desarrollo personal y profesional", "Competencias y certificaciones", "Qué aprender fuera de la malla para destacar, en qué orden y qué certificaciones valoran los empleadores.",
    table(["Prioridad", "Competencia", "Cómo demostrarla"], [["1", "<b>Excel avanzado</b>: BUSCARX, SUMAR.SI.CONJUNTO, tablas dinámicas, Power Query, Solver", "Un modelo de evaluación de proyecto o planificación propio"], ["2", "<b>Visualización y BI</b>: Power BI o Tableau, DAX básico", "Un dashboard publicado con datos públicos (INE, CMF, Banco Central)"], ["3", "<b>SQL</b>: SELECT, JOIN, GROUP BY, ventanas", "Ejercicios en plataformas gratuitas; consultas sobre una base real"], ["4", "<b>Python para análisis</b>: pandas, matplotlib, PuLP/OR-Tools, SimPy", "Un repositorio con un análisis o un optimizador"], ["5", "<b>Lean Six Sigma</b>", "Certificación Yellow/Green Belt con un proyecto real"], ["6", "<b>Gestión de proyectos</b>", "CAPM (sin experiencia) o PMP (con 3 años); Scrum (PSM I)"], ["7", "<b>Inglés técnico</b> (B2 o más)", "Examen internacional o entrevistas en inglés"], ["8", "<b>ERP</b>: SAP (MM, PP, SD) u Oracle", "Curso o experiencia en práctica"], ["9", "<b>Normas ISO</b>: 9001, 14001, 45001", "Curso de auditor interno"], ["10", "<b>Comunicación ejecutiva</b>", "Presentaciones de 10 minutos con una recomendación clara"]]) +
    h3("Certificaciones más valoradas") + table(["Certificación", "Organismo", "Para quién"], [["Lean Six Sigma Yellow / Green / Black Belt", "ASQ, IASSC u organismos locales", "Calidad, operaciones, mejora continua"], ["CAPM / PMP", "Project Management Institute (PMI)", "Proyectos e inversión"], ["PSM I / CSM", "Scrum.org / Scrum Alliance", "Proyectos de tecnología y transformación"], ["CPIM / CSCP", "ASCM (ex APICS)", "Planificación y supply chain"], ["Auditor interno ISO 9001/14001/45001", "Organismos certificadores", "Calidad, HSE"], ["Microsoft PL-300 (Power BI)", "Microsoft", "Análisis de datos"], ["Excel Expert (MO-201)", "Microsoft", "Todos"], ["CFA nivel I", "CFA Institute", "Finanzas e inversiones"]]) +
    h3("Habilidades blandas que más pesan") + '<div class="prose"><ul><li><b>Estructurar problemas</b>: separar un problema grande en partes medibles (árbol de problemas, MECE).</li><li><b>Comunicar con números</b>: empezar por la conclusión y respaldarla con 3 datos.</li><li><b>Trabajar en planta</b>: escuchar a operadores y supervisores; el mejor dato está en terreno (gemba).</li><li><b>Negociar y gestionar el cambio</b>: una mejora que nadie adopta no vale nada.</li></ul></div>');
}

function pgPractica(){
  return pg("Carrera · Titulación", "Práctica profesional y memoria de título", "Cómo aprovechar la práctica, elegir un buen tema de memoria y llegar al examen de título con un trabajo sólido.",
    acc([
      ["Antes de la práctica", "<ul><li>Postula con 3 a 4 meses de anticipación (bolsas de la universidad, LinkedIn, ferias laborales).</li><li>Prepara un CV de una página y un párrafo que diga qué problema te gustaría resolver.</li><li>Pregunta en la entrevista qué proyecto tendrás y quién será tu supervisor.</li></ul>"],
      ["Durante la práctica: plan de 10 semanas", "<ol><li><b>Semanas 1–2:</b> conoce el proceso (SIPOC, VSM), los indicadores y a las personas. Define con tu jefe un problema y una meta medible.</li><li><b>Semanas 3–5:</b> levanta datos (tiempos, demandas, defectos, costos). Usa Pareto e Ishikawa para enfocarte.</li><li><b>Semanas 6–8:</b> diseña y prueba la mejora (piloto). Cuantifica antes y después.</li><li><b>Semanas 9–10:</b> evalúa económicamente, documenta el estándar y presenta a la jefatura.</li></ol><p>Lleva una bitácora diaria: te ahorrará días al escribir el informe.</p>"],
      ["Informe de práctica", "<p>Estructura habitual: portada, resumen, descripción de la empresa y del área, actividades realizadas, proyecto o problema abordado (situación actual → análisis → propuesta → resultados), conclusiones y aprendizajes, anexos. Usa el " + lk("generador-informe", "generador de informe") + " y las " + lk("plantillas", "plantillas") + ".</p>"],
      ["Cómo elegir el tema de memoria", "<ul><li>Un problema <b>real</b> de una organización, con datos disponibles y un contraparte que lo patrocine.</li><li>Con <b>impacto medible</b> (costos, tiempos, nivel de servicio, accidentes).</li><li>Acotado: debe terminarse en 4 a 6 meses.</li><li>Que use herramientas de ingeniería (optimización, simulación, estadística, evaluación económica), no solo descripción.</li></ul><p><b>Ejemplos:</b> rediseño de layout de bodega; modelo de pronóstico y política de inventario; programación de turnos con programación entera; plan de mantenimiento basado en confiabilidad; evaluación de un proyecto de automatización; reducción de mermas con DMAIC.</p>"],
      ["Estructura de la memoria", "<ol><li>Introducción: contexto, problema, justificación.</li><li>Objetivos: general y específicos (verbos medibles).</li><li>Marco teórico: solo lo que se usa.</li><li>Metodología: pasos, datos, herramientas.</li><li>Diagnóstico de la situación actual.</li><li>Propuesta de solución y su validación.</li><li>Evaluación económica (VAN, TIR, sensibilidad).</li><li>Plan de implementación.</li><li>Conclusiones y recomendaciones.</li><li>Referencias (APA) y anexos.</li></ol>"],
      ["Examen de título (defensa)", "<ul><li>20 a 30 minutos: problema (2 min) → objetivos → metodología → resultados clave → evaluación económica → conclusiones.</li><li>Una idea por lámina; gráficos en vez de tablas.</li><li>Prepara respuestas para: supuestos, limitaciones, sensibilidad del VAN, por qué ese método y no otro, qué harías distinto.</li></ul>"]
    ], true));
}

function pgEmpleo(){
  return pg("Carrera · Empleabilidad", "CV, entrevistas y primer trabajo", "Cómo presentarte, cómo responder en entrevistas (incluidos casos y estimaciones) y cómo partir bien en tu primer empleo.",
    acc([
      ["CV de una página", "<ul><li>Arriba: nombre, título, ciudad, correo, teléfono, LinkedIn.</li><li>Un resumen de 2 líneas con lo que sabes hacer y lo que buscas.</li><li>Experiencia y proyectos con viñetas de logro: <b>verbo + qué hiciste + resultado medible</b>.<br><i>Ej.: «Rediseñé el picking de la bodega central con clasificación ABC, reduciendo el tiempo de preparación en 23 %».</i></li><li>Herramientas con nivel (Excel avanzado, Power BI intermedio, Python básico).</li><li>Sin foto ni datos personales innecesarios; en PDF.</li></ul>"],
      ["Método STAR para preguntas de comportamiento", "<p><b>S</b>ituación (contexto breve) → <b>T</b>area (tu responsabilidad) → <b>A</b>cción (lo que hiciste tú) → <b>R</b>esultado (con números y lo aprendido).</p><p>Prepara 6 historias: un logro, un conflicto, un error, liderazgo, trabajo bajo presión, una mejora que propusiste.</p>"],
      ["Preguntas frecuentes", "<ul><li>¿Por qué ingeniería industrial y por qué esta empresa?</li><li>Cuéntame de un proyecto en el que mejoraste algo.</li><li>¿Cómo priorizas cuando tienes varias tareas urgentes?</li><li>¿Qué harías si los datos contradicen la opinión del jefe de planta?</li><li>Explícame el VAN a alguien que no es ingeniero.</li><li>¿Qué indicadores usarías para medir esta área?</li></ul>"],
      ["Casos de negocio y estimaciones (guesstimates)", "<p>Estructura: <b>aclarar</b> el objetivo → <b>estructurar</b> en un árbol (ingresos = precio × cantidad; costos fijos + variables) → <b>supuestos</b> explícitos → <b>calcular</b> en voz alta → <b>validar</b> el orden de magnitud → <b>recomendar</b>.</p><p><i>Ejemplo:</i> ¿Cuántos litros de café se venden al día en Santiago? Población (~7 millones) × % que toma café fuera de casa × tazas por día × tamaño de taza.</p>"],
      ["Primeros 90 días", "<ol><li><b>Días 1–30:</b> escucha, aprende el proceso en terreno, entiende cómo te van a medir.</li><li><b>Días 31–60:</b> elige una mejora rápida y visible; entrégala.</li><li><b>Días 61–90:</b> propone un proyecto mayor con caso de negocio.</li></ol><p>Documenta todo lo que hagas: es la base de tu próxima evaluación y de tu CV.</p>"],
      ["Contrato y remuneración en Chile", "<ul><li>Revisa: tipo de contrato (plazo fijo o indefinido), jornada (42 h semanales desde abril de 2026, Ley 21.561), sueldo base y variables, gratificación legal, beneficios.</li><li>El sueldo líquido descuenta AFP (~10 % + comisión), salud (7 % o plan Isapre), seguro de cesantía (0,6 % en contrato indefinido) e impuesto único si corresponde.</li><li>Negocia con datos: estudios de remuneraciones y ofertas comparables.</li></ul>"]
    ], true));
}

function pgSoftware(){
  return pg("Carrera · Herramientas digitales", "Software del ingeniero industrial", "Las herramientas que vas a usar y lo mínimo que conviene dominar de cada una.",
    note("<b>Practica sin instalar nada:</b> en " + lk("simuladores", "Simuladores de software") + " tienes versiones de práctica de MS Project, Minitab, Arena, SAP, LINGO, Power BI, SQL y AutoCAD, cada una con instructivo.", "info") +
    table(["Herramienta", "Para qué", "Lo esencial"], [["Excel", "Todo: modelos, planillas, análisis", "BUSCARX/INDICE-COINCIDIR, SUMAR.SI.CONJUNTO, tablas dinámicas, Power Query, Solver, VNA/TIR.NO.PER, escenarios"], ["Power BI / Tableau", "Dashboards e indicadores", "Modelo de datos en estrella, medidas DAX, filtros, publicación"], ["SQL", "Consultar bases de datos", "SELECT, WHERE, JOIN, GROUP BY, subconsultas, funciones de ventana"], ["Python", "Análisis, automatización, optimización", "pandas, numpy, matplotlib, scipy.stats, PuLP/OR-Tools, SimPy"], ["R / Minitab", "Estadística y calidad", "Pruebas de hipótesis, ANOVA, cartas de control, capacidad"], ["Arena / FlexSim / AnyLogic", "Simulación de procesos", "Llegadas, colas, recursos, validación, escenarios"], ["MS Project / Primavera P6", "Planificación de proyectos", "EDT, dependencias, ruta crítica, línea base, recursos"], ["SAP / ERP", "Gestión integrada", "Maestros de materiales, órdenes de compra y producción, MRP"], ["AutoCAD / Visio / Draw.io", "Layout y diagramas", "Planos de planta, diagramas de flujo, BPMN"], ["Lingo / Gurobi / CPLEX", "Optimización avanzada", "Modelos lineales y enteros de gran tamaño"]]) +
    h3("Atajos de Excel que ahorran horas") + table(["Atajo", "Acción"], [["Ctrl + T", "Convertir rango en tabla"], ["Ctrl + Shift + L", "Activar filtros"], ["Alt + =", "Autosuma"], ["F4", "Fijar referencia ($A$1)"], ["Ctrl + flecha", "Ir al final de los datos"], ["Ctrl + ;", "Fecha de hoy"], ["Alt + N + V", "Tabla dinámica"], ["Ctrl + 1", "Formato de celdas"]], { cls:"ftab" }));
}

/* ============ CONTENIDO: GESTIÓN Y MEJORA ============ */
function pgLean(){
  return pg("Gestión · Lean manufacturing", "Lean y mejora continua", "Los principios y herramientas del Sistema de Producción Toyota para eliminar desperdicios y hacer fluir el valor.",
    h3("Los 5 principios Lean") + '<ol class="prose"><li><b>Valor:</b> lo define el cliente.</li><li><b>Flujo de valor:</b> mapear todos los pasos y separar los que agregan valor.</li><li><b>Flujo:</b> que el producto avance sin esperas.</li><li><b>Pull:</b> producir solo lo que el cliente consume.</li><li><b>Perfección:</b> mejorar continuamente (kaizen).</li></ol>' +
    h3("Los 8 desperdicios (TIMWOODS)") + table(["Desperdicio", "Ejemplo", "Contramedida"], [["Transporte", "Mover material entre bodegas lejanas", "Layout en flujo, celdas"], ["Inventario", "Stock entre procesos", "Pull, kanban, lotes pequeños"], ["Movimiento", "Operario que camina a buscar herramientas", "5S, puesto ergonómico"], ["Esperas", "Máquina detenida esperando material", "Balanceo, SMED, TPM"], ["Sobreproducción", "Producir antes de que se necesite", "Takt, nivelación (heijunka)"], ["Sobreprocesamiento", "Tolerancias más estrictas que lo pedido", "Entender requisitos del cliente"], ["Defectos", "Reprocesos y rechazos", "Poka-yoke, jidoka, SPC"], ["Talento no usado", "No escuchar ideas de los operarios", "Kaizen, sistemas de sugerencias"]]) +
    acc([
      ["5S", "<p><b>Seiri</b> (clasificar: eliminar lo innecesario, tarjeta roja), <b>Seiton</b> (ordenar: un lugar para cada cosa), <b>Seiso</b> (limpiar e inspeccionar), <b>Seiketsu</b> (estandarizar), <b>Shitsuke</b> (disciplina: auditorías periódicas).</p>"],
      ["SMED (cambio rápido de formato)", "<ol><li>Observar y filmar el cambio.</li><li>Separar actividades internas (máquina detenida) y externas.</li><li>Convertir internas en externas (preparar antes).</li><li>Optimizar ambas (fijaciones rápidas, eliminar ajustes, trabajo en paralelo).</li></ol><p>Meta: cambios de un dígito (menos de 10 minutos).</p>"],
      ["Kanban y sistema pull", "<p>Tarjetas que autorizan producir o mover. Número de kanbans: <b>N = D × L × (1 + α) ÷ C</b> (demanda por período, lead time, factor de seguridad, capacidad del contenedor).</p>"],
      ["TPM (mantenimiento productivo total)", "<p>Pilares: mantenimiento autónomo, planificado, mejora enfocada, calidad, capacitación, seguridad, oficinas, gestión temprana. Se mide con el " + lk("oee", "OEE") + ", MTBF y MTTR.</p>"],
      ["Poka-yoke y jidoka", "<p><b>Poka-yoke:</b> dispositivo que impide o detecta el error (pin guía, sensor de presencia). <b>Jidoka:</b> la máquina se detiene sola ante una anomalía (andon).</p>"],
      ["Trabajo estandarizado", "<p>Tres elementos: takt time, secuencia de trabajo y inventario estándar en proceso. Es la base para mejorar: sin estándar no hay mejora.</p>"],
      ["Herramientas de esta app", '<div class="quick">' + ["vsm", "balanceo", "oee", "tiempo-estandar", "pareto", "ishikawa", "porques"].map(id => '<button class="chip" type="button" data-go="' + id + '">' + C[id].t + "</button>").join("") + "</div>"]
    ]));
}

function pgMejora(){
  return pg("Gestión · Metodologías", "Metodologías de mejora: PDCA, DMAIC, 8D y A3", "Cuándo usar cada metodología de solución de problemas y qué entregar en cada etapa.",
    table(["Metodología", "Cuándo usarla", "Etapas"], [["PDCA (Deming)", "Mejora continua del día a día", "Planificar → Hacer → Verificar → Actuar"], ["DMAIC (Seis Sigma)", "Problemas complejos con datos y variabilidad", "Definir → Medir → Analizar → Mejorar → Controlar"], ["8D (automotriz)", "Reclamos de clientes y no conformidades", "Equipo → Problema → Contención → Causa raíz → Acción correctiva → Implementar → Prevenir → Reconocer"], ["A3 (Toyota)", "Resolver y comunicar en una hoja", "Contexto → Situación actual → Meta → Análisis → Contramedidas → Plan → Seguimiento"], ["Kaizen (evento)", "Mejora rápida en un área acotada (3 a 5 días)", "Preparación → Diagnóstico → Implementación en terreno → Estandarización"]]) +
    h3("DMAIC: entregables por etapa") + table(["Etapa", "Pregunta", "Herramientas"], [["Definir", "¿Cuál es el problema y qué vale para el cliente?", "Project charter, SIPOC, voz del cliente, CTQ"], ["Medir", "¿Cuánto y con qué frecuencia ocurre?", "Plan de recolección, MSA (R&R), capacidad, nivel sigma"], ["Analizar", "¿Por qué ocurre?", "Pareto, Ishikawa, 5 porqués, regresión, pruebas de hipótesis"], ["Mejorar", "¿Qué solución elimina la causa?", "Lluvia de ideas, matriz de selección, diseño de experimentos, piloto"], ["Controlar", "¿Cómo aseguro que se mantenga?", "Plan de control, SPC, estándares, poka-yoke"]]) +
    h3("Herramientas relacionadas") + '<div class="quick">' + ["sipoc", "capacidad", "sigma", "pareto", "ishikawa", "porques", "control-xr", "amef"].map(id => '<button class="chip" type="button" data-go="' + id + '">' + C[id].t + "</button>").join("") + "</div>");
}

function pgCalidad7(){
  return pg("Gestión · Calidad", "Las 7 herramientas básicas de la calidad", "Las herramientas de Ishikawa resuelven la gran mayoría de los problemas de calidad en planta.",
    table(["Herramienta", "Pregunta que responde", "En la app"], [["Hoja de verificación", "¿Qué, dónde y cuántas veces ocurre?", "—"], ["Histograma", "¿Cómo se distribuyen los datos?", lk("descriptiva", "Estadística descriptiva")], ["Diagrama de Pareto", "¿Cuáles son las causas principales?", lk("pareto", "Pareto")], ["Diagrama causa-efecto", "¿Qué causas posibles hay?", lk("ishikawa", "Ishikawa")], ["Diagrama de dispersión", "¿Se relacionan dos variables?", lk("regresion", "Regresión")], ["Gráfico de control", "¿El proceso es estable?", lk("control-xr", "X̄-R") + " · " + lk("control-p", "p")], ["Estratificación / flujograma", "¿Difiere por turno, máquina, proveedor?", lk("sipoc", "SIPOC")]]) +
    h3("Costos de la calidad (modelo PAF)") + table(["Categoría", "Ejemplos"], [["Prevención", "Capacitación, diseño robusto, AMEF, mantenimiento preventivo"], ["Evaluación", "Inspección, ensayos, calibración, auditorías"], ["Fallas internas", "Scrap, reprocesos, paradas por calidad"], ["Fallas externas", "Garantías, devoluciones, reclamos, pérdida de clientes"]]) +
    note("Invertir en prevención reduce mucho más los costos de falla. Una falla externa puede costar 10 a 100 veces más que prevenirla.", "info"));
}

function pgProyectos(){
  return pg("Gestión · Proyectos", "Gestión de proyectos", "Fases, entregables e indicadores de un proyecto bien gestionado (PMBOK y prácticas ágiles).",
    table(["Fase", "Entregables clave"], [["Inicio", "Acta de constitución (objetivo, alcance, presupuesto, patrocinador), registro de interesados"], ["Planificación", "EDT (estructura de desglose del trabajo), cronograma (" + lk("cpm", "CPM") + " y Gantt), presupuesto, matriz de riesgos, " + lk("raci", "RACI") + ", plan de comunicaciones"], ["Ejecución", "Entregables, gestión del equipo, compras y contratos"], ["Monitoreo y control", "Valor ganado, control de cambios, informes de avance"], ["Cierre", "Aceptación formal, lecciones aprendidas, cierre de contratos"]]) +
    h3("Valor ganado (EVM)") + table(["Indicador", "Fórmula", "Lectura"], [["PV (valor planificado)", "Presupuesto del trabajo programado a la fecha", ""], ["EV (valor ganado)", "% de avance real × presupuesto total", ""], ["AC (costo real)", "Lo gastado a la fecha", ""], ["SV / SPI", "EV − PV · EV ÷ PV", "SPI < 1: atrasado"], ["CV / CPI", "EV − AC · EV ÷ AC", "CPI < 1: sobrecosto"], ["EAC", "BAC ÷ CPI", "Costo final estimado"], ["ETC", "EAC − AC", "Lo que falta gastar"]], { cls:"ftab" }) +
    h3("Ágil (Scrum) en proyectos de ingeniería") + '<div class="prose"><p>Útil cuando el alcance es incierto (software, transformación digital, innovación): sprints de 1 a 4 semanas, backlog priorizado por valor, reuniones diarias de 15 minutos, revisión y retrospectiva al final de cada sprint.</p></div>' +
    h3("Matriz de riesgos del proyecto") + '<div class="prose"><p>Para cada riesgo: causa → evento → efecto; probabilidad e impacto (1 a 5); respuesta (evitar, transferir, mitigar o aceptar); responsable y disparador. Complementa con ' + lk("simulacion-mc", "simulación Monte Carlo") + ' para el costo y el plazo.</p></div>');
}

