  ["Producción", "OEE", "Disponibilidad × Rendimiento × Calidad", "≥ 85 % clase mundial"], ["Producción", "Cumplimiento del plan", "Producción real ÷ planificada", "≥ 95 %"], ["Producción", "Productividad de mano de obra", "Unidades ÷ horas hombre", "Tendencia creciente"], ["Producción", "Scrap", "Unidades rechazadas ÷ producidas", "< 2 % (según industria)"],
  ["Mantenimiento", "MTBF", "Tiempo operativo ÷ n.º de fallas", "Creciente"], ["Mantenimiento", "MTTR", "Tiempo total de reparación ÷ n.º de fallas", "Decreciente"], ["Mantenimiento", "Disponibilidad", "MTBF ÷ (MTBF + MTTR)", "≥ 90 %"], ["Mantenimiento", "% preventivo", "HH preventivas ÷ HH totales", "≥ 70 %"],
  ["Logística", "OTIF", "Pedidos a tiempo y completos ÷ pedidos totales", "≥ 95 %"], ["Logística", "Fill rate", "Unidades despachadas ÷ solicitadas", "≥ 98 %"], ["Logística", "Rotación de inventario", "Costo de ventas ÷ inventario promedio", "Según industria"], ["Logística", "Exactitud de inventario", "Ítems sin diferencia ÷ ítems contados", "≥ 98 %"], ["Logística", "Costo logístico", "Costo logístico ÷ ventas", "5 % – 12 %"],
  ["Calidad", "PPM", "Defectuosos × 10⁶ ÷ unidades", "Decreciente"], ["Calidad", "Rendimiento al primer intento (FPY)", "Buenas sin reproceso ÷ entradas", "≥ 95 %"], ["Calidad", "Costo de no calidad", "Fallas internas + externas ÷ ventas", "< 2 %"],
  ["Seguridad", "Tasa de accidentabilidad", "Accidentes CTP ÷ trabajadores × 100", "< 2 %"], ["Seguridad", "Índice de frecuencia", "Accidentes × 10⁶ ÷ HHT", "Decreciente"],
  ["Finanzas", "Margen EBITDA", "EBITDA ÷ ventas", "Según industria"], ["Finanzas", "Capital de trabajo (días)", "Días de inventario + cobro − pago", "Decreciente"], ["Personas", "Rotación de personal", "Egresos ÷ dotación promedio", "< 10 % anual"], ["Personas", "Ausentismo", "Días ausentes ÷ días programados", "< 3 %"]
