function pgKpis(){
  const areas = [...new Set(KPIS.map(k => k[0]))];
  return pg("Gestión · Indicadores", "Biblioteca de KPI", "Indicadores clave por área, con su fórmula y referencia. Un buen KPI es específico, medible, tiene dueño, meta y frecuencia de revisión.",
    acc(areas.map(a => [a, table(["Indicador", "Fórmula", "Referencia"], KPIS.filter(k => k[0] === a).map(k => ["<b>" + k[1] + "</b>", k[2], k[3]]))]), true) +
    h3("Ficha de un indicador") + table(["Campo", "Contenido"], [["Nombre y objetivo", "Qué mide y para qué decisión sirve"], ["Fórmula", "Numerador, denominador, unidades"], ["Fuente de datos", "Sistema o registro y su confiabilidad"], ["Frecuencia", "Diaria, semanal, mensual"], ["Meta y umbrales", "Verde, amarillo, rojo"], ["Responsable", "Quién lo mide y quién actúa"], ["Visualización", "Gráfico de tendencia con meta, no solo el valor del mes"]], { cls:"ftab" }));
}

/* ============ CONTENIDO: INFORMES ============ */
function pgEstructura(){
  return pg("Informes · Estructura", "Cómo estructurar un informe técnico", "La estructura estándar de un informe de ingeniería, qué va en cada parte y los errores más comunes.",
    table(["Sección", "Contenido", "Extensión"], [["Portada", "Título específico, autor, institución, destinatario, fecha", "1 pág."], ["Resumen ejecutivo", "Problema, método, resultado principal con cifras, recomendación. Se escribe al final.", "½ a 1 pág."], ["Índice", "De contenidos, tablas y figuras", "—"], ["1. Introducción", "Contexto, problema, justificación (por qué importa, cuánto cuesta)", "1–2 pág."], ["2. Objetivos", "General (qué y para qué) y específicos (cómo), con verbos medibles", "½ pág."], ["3. Marco teórico", "Solo conceptos y métodos que se usan después, con referencias", "2–4 pág."], ["4. Metodología", "Pasos, datos, fuentes, supuestos, herramientas", "1–3 pág."], ["5. Resultados", "Hechos y datos, en tablas y gráficos numerados", "Variable"], ["6. Análisis / discusión", "Qué significan los resultados, comparación con la meta, limitaciones", "Variable"], ["7. Conclusiones", "Respuesta a cada objetivo, en el mismo orden", "1 pág."], ["8. Recomendaciones", "Acciones concretas con responsable, plazo y costo", "½ pág."], ["Referencias", "Formato APA 7, solo lo citado", "—"], ["Anexos", "Datos brutos, cálculos extensos, planos, cotizaciones", "—"]]) +
    acc([
      ["Objetivos bien redactados", "<p>Verbo en infinitivo + qué + para qué o con qué alcance. Usa verbos medibles: <i>determinar, cuantificar, diseñar, evaluar, proponer, comparar, reducir</i>. Evita <i>conocer, entender, estudiar</i>.</p><p><b>Mal:</b> «Estudiar la bodega». <b>Bien:</b> «Diseñar un layout de bodega que reduzca en 20 % la distancia recorrida en el picking».</p>"],
      ["Tablas y figuras", "<ul><li>Numeradas y con título: «Tabla 3. Costos anuales por alternativa». En APA, el título va arriba tanto en tablas como en figuras.</li><li>Cita la fuente debajo («Fuente: elaboración propia con datos de la empresa»).</li><li>Toda tabla o figura se menciona y se comenta en el texto.</li><li>Unidades en el encabezado de la columna, no en cada celda.</li><li>Gráficos: barras para comparar categorías, líneas para tendencias, dispersión para relaciones. Evita tortas con más de 4 partes y gráficos 3D.</li></ul>"],
      ["Números y unidades (SI)", "<ul><li>En Chile: coma decimal y punto o espacio para miles (1.250,5).</li><li>Espacio entre número y unidad: 25 kg, 3,5 m, 12 %. Símbolos sin punto ni plural (kg, no Kg. ni kgs).</li><li>Moneda: $ 1.250.000 o MM$ 1,25; indica si incluye IVA y la fecha de los precios (UF del día).</li><li>Cifras significativas coherentes con la precisión del dato.</li></ul>"],
      ["Errores frecuentes", "<ul><li>Conclusiones que no responden a los objetivos.</li><li>Resultados sin análisis, o análisis sin datos.</li><li>Marco teórico copiado de libros que no se usa después.</li><li>Recomendaciones vagas («mejorar la comunicación»).</li><li>Texto en primera persona coloquial; usa impersonal («se midió», «se propone»).</li><li>Párrafos de una sola oración o de media página.</li></ul>"],
      ["Lista de verificación antes de entregar", "<ul><li>¿El resumen se entiende sin leer el resto?</li><li>¿Cada objetivo tiene su resultado y su conclusión?</li><li>¿Todas las tablas y figuras están numeradas, tituladas y citadas en el texto?</li><li>¿Las cifras del resumen coinciden con las del cuerpo?</li><li>¿Las referencias tienen formato APA y aparecen citadas?</li><li>¿Revisaste ortografía y formato uniforme (fuente, interlineado, márgenes)?</li></ul>"]
    ]));
}

function pgRedaccion(){
  return pg("Informes · Comunicación", "Redacción técnica y presentaciones", "Cómo escribir claro, presentar números y exponer ante una gerencia o una comisión.",
    acc([
      ["Principios de redacción técnica", "<ul><li><b>Conclusión primero</b> (pirámide de Minto): idea principal → argumentos → datos.</li><li>Una idea por párrafo; oraciones de 15 a 25 palabras.</li><li>Concreto y cuantificado: «redujo el tiempo de 78 a 31 min» en vez de «redujo bastante el tiempo».</li><li>Términos consistentes: si dices «línea 3», no la llames después «la envasadora».</li><li>Define siglas la primera vez: Overall Equipment Effectiveness (OEE).</li></ul>"],
      ["Verbos para objetivos (taxonomía de Bloom)", "<p><b>Conocer:</b> identificar, describir, enumerar. <b>Comprender:</b> explicar, clasificar, comparar. <b>Aplicar:</b> calcular, implementar, utilizar. <b>Analizar:</b> diagnosticar, determinar, cuantificar. <b>Evaluar:</b> evaluar, seleccionar, justificar. <b>Crear:</b> diseñar, proponer, desarrollar, formular.</p><p>Un objetivo general de memoria suele estar en los niveles evaluar o crear.</p>"],
      ["Conectores útiles", "<p><b>Adición:</b> además, asimismo. <b>Contraste:</b> sin embargo, no obstante, en cambio. <b>Causa:</b> debido a, puesto que. <b>Consecuencia:</b> por lo tanto, en consecuencia. <b>Ejemplo:</b> por ejemplo, en particular. <b>Cierre:</b> en síntesis, en conclusión.</p>"],
      ["Presentación oral", "<ul><li>Regla 10–20–30: máximo 10 láminas clave, 20 minutos, letra de 30 puntos o más.</li><li>Título de cada lámina = su conclusión («El 72 % de las paradas se debe a 3 causas»), no el tema («Paradas»).</li><li>Un gráfico por lámina, con lo importante destacado en color.</li><li>Estructura: problema → impacto en $ → causa → solución → beneficio → próximos pasos y lo que necesitas de la audiencia.</li><li>Ensaya con cronómetro y prepara láminas de respaldo para las preguntas.</li></ul>"],
      ["Correo profesional", "<ul><li>Asunto específico: «Aprobación compra de sensor – línea 3 – antes del 15/11».</li><li>Primera línea: lo que necesitas y para cuándo.</li><li>Contexto breve en viñetas; adjuntos con nombre claro.</li><li>Cierre con próximo paso y firma completa.</li></ul>"]
    ], true));
}

