function pgTablas(){
  const zrow = [0, 0.5, 1, 1.28, 1.5, 1.645, 1.96, 2, 2.326, 2.5, 2.576, 3];
  const tdf = [1, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 25, 30, 40, 60, 120];
  return pg("Aprender · Tablas", "Tablas de referencia", "Tablas estadísticas, constantes de control y equivalencias calculadas por la app. Cada tabla explica para qué sirve, cómo se lee y trae un ejemplo.",
    acc([
      ["Distribución normal estándar", "<p><b>Para qué sirve:</b> calcular probabilidades cuando los datos siguen la campana de Gauss (pesos, dimensiones, tiempos promedio) y obtener el factor z para niveles de servicio o de confianza.</p><p><b>Cómo leerla:</b> z indica a cuántas desviaciones estándar está un valor del promedio: <m>z = (x − μ) ÷ σ</m>. Φ(z) es la probabilidad de obtener un valor menor que ese. <b>Ejemplo:</b> si un envase pesa en promedio 500 g con σ = 2 g, ¿qué porcentaje pesa más de 504 g? z = (504 − 500) ÷ 2 = 2; la cola derecha para z = 2 es 0,0228, es decir, 2,3 %.</p>" + table(["z", "Φ(z) acumulada", "Área cola derecha", "Área ±z (bilateral)"], zrow.map(z => [nf(z, 3), nf(Phi(z), 4), nf(1 - Phi(z), 4), nf(2 * Phi(z) - 1, 4)]), { num:[0, 1, 2, 3] }) + table(["Confianza", "z bilateral", "z unilateral"], [0.8, 0.9, 0.95, 0.98, 0.99, 0.995, 0.999].map(c => [pc(c), nf(invNorm(1 - (1 - c) / 2), 3), nf(invNorm(c), 3)]), { num:[1, 2] })],
      ["t de Student (valores críticos bilaterales)", "<p><b>Para qué sirve:</b> construir intervalos de confianza y pruebas cuando la muestra es pequeña y no se conoce la desviación real de la población.</p><p><b>Cómo leerla:</b> busca la fila de los grados de libertad (gl = n − 1) y la columna del nivel de confianza. <b>Ejemplo:</b> con 10 mediciones (gl = 9, usa la fila más cercana) y 95 %, t ≈ 2,26: el intervalo es x̄ ± 2,26 × s ÷ √10. Con muchos datos, t se acerca a 1,96 (el valor de la normal).</p>" + table(["gl", "90 %", "95 %", "99 %"], tdf.map(d => [d, nf(tInv(0.95, d), 3), nf(tInv(0.975, d), 3), nf(tInv(0.995, d), 3)]), { num:[0, 1, 2, 3] })],
      ["Constantes para gráficos de control", "<p><b>Para qué sirve:</b> calcular los límites de los gráficos X̄-R sin calcular desviaciones estándar.</p><p><b>Cómo leerla:</b> n es el tamaño de cada subgrupo (por ejemplo, 5 piezas cada hora). <b>Ejemplo:</b> con n = 5, A₂ = 0,577; si X̿ = 50,0 y R̄ = 2,0, los límites del gráfico de promedios son 50 ± 0,577 × 2 = 48,85 a 51,15. Para el gráfico de rangos, LSC = D₄ × R̄ = 2,114 × 2 = 4,23 y LIC = D₃ × R̄ = 0. d₂ convierte el rango promedio en desviación estándar: σ ≈ R̄ ÷ d₂.</p>" + table(["n", "A₂", "D₃", "D₄", "d₂"], Object.keys(CC).map(n => [n].concat(CC[n].map(x => nf(x, 3)))), { num:[0, 1, 2, 3, 4] })],
      ["Valoración del ritmo (Westinghouse)", "<p><b>Para qué sirve:</b> ajustar el tiempo cronometrado según cómo trabajaba la persona observada.</p><p><b>Cómo leerla:</b> se suman los factores de habilidad, esfuerzo, condiciones y consistencia, y se suma 1. <b>Ejemplo:</b> habilidad buena (+0,06), esfuerzo bueno (+0,05), condiciones promedio (0) y consistencia promedio (0) dan 1,11: el tiempo normal es 11 % mayor que el observado.</p>" + table(["Factor", "Superior", "Excelente", "Buena", "Promedio", "Regular", "Deficiente"], [["Habilidad", "+0,15", "+0,11", "+0,06", "0", "−0,05", "−0,16"], ["Esfuerzo", "+0,13", "+0,10", "+0,05", "0", "−0,04", "−0,12"], ["Condiciones", "+0,06", "+0,04", "+0,02", "0", "−0,03", "−0,07"], ["Consistencia", "+0,04", "+0,03", "+0,01", "0", "−0,02", "−0,04"]]) + "<p class='hint'>Valoración = 1 + suma de los cuatro factores (valores medios de cada categoría).</p>"],
      ["Prefijos del Sistema Internacional", "<p><b>Para qué sirve:</b> leer y convertir unidades grandes y pequeñas. Ejemplo: 3,5 MW = 3.500 kW = 3.500.000 W; 250 mm = 0,25 m.</p>" + table(["Prefijo", "Símbolo", "Factor"], [["giga", "G", "10⁹"], ["mega", "M", "10⁶"], ["kilo", "k", "10³"], ["hecto", "h", "10²"], ["deci", "d", "10⁻¹"], ["centi", "c", "10⁻²"], ["mili", "m", "10⁻³"], ["micro", "µ", "10⁻⁶"], ["nano", "n", "10⁻⁹"]])],
      ["Factores de interés compuesto (calculadora)", "<p><b>Para qué sirve:</b> reemplaza las tablas de factores de los libros de ingeniería económica. Cada factor convierte un tipo de flujo en otro. Se lee «lo que busco / lo que tengo»: (P/F) da el valor presente de un monto futuro; (A/P) da la cuota de un préstamo; (F/A) el valor futuro de una serie de cuotas.</p><p><b>Ejemplo:</b> con i = 10 % y n = 5, (A/P) = 0,2638: un préstamo de $ 1.000.000 se paga con 5 cuotas anuales de $ 263.800.</p>" + '<div class="grid" style="max-width:420px"><div class="field"><label for="tfi">Tasa i (%)</label><input id="tfi" type="text" inputmode="decimal" value="10"></div><div class="field"><label for="tfn">Hasta n</label><input id="tfn" type="text" inputmode="numeric" value="15"></div></div><div id="tfout"></div>']
    ], true));
}
function tfTable(){ const el = document.getElementById("tfout"); if (!el) return; const i = num(document.getElementById("tfi").value) / 100, N = Math.min(100, Math.max(1, Math.round(num(document.getElementById("tfn").value) || 1))); if (!fin(i)) { el.innerHTML = note("Tasa inválida.", "bad"); return; } const R = []; for (let n = 1; n <= N; n++) { const k = fct(i, n); R.push([n, nf(k.FP, 4), nf(k.PF, 4), nf(k.AP, 4), nf(k.PA, 4), nf(k.AF, 4), nf(k.FA, 4)]); } el.innerHTML = table(["n", "F/P", "P/F", "A/P", "P/A", "A/F", "F/A"], R, { num:[0, 1, 2, 3, 4, 5, 6], tall:true }); }

